import{_ as a,o as e,c as d,a2 as o}from"./chunks/framework.kOe0DhAP.js";const p=JSON.parse('{"title":"技术栈","description":"按技术承担的职责理解系统，而不是只记住组件名称。","frontmatter":{"title":"技术栈","description":"按技术承担的职责理解系统，而不是只记住组件名称。"},"headers":[],"relativePath":"introduction/technology.md","filePath":"introduction/technology.md"}'),r={name:"introduction/technology.md"};function i(n,t,l,c,s,h){return e(),d("div",null,[...t[0]||(t[0]=[o('<div class="doc-eyebrow">项目介绍 / TGEX KNOWLEDGE BASE</div><h1 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h1><div class="doc-lead">按技术承担的职责理解系统，而不是只记住组件名称。</div><h2 id="已观察到的技术组成" tabindex="-1">已观察到的技术组成 <a class="header-anchor" href="#已观察到的技术组成" aria-label="Permalink to &quot;已观察到的技术组成&quot;">​</a></h2><p>工程以 Java、Maven、Spring Boot 2.x 和 Dubbo 为主要服务基础；数据访问使用 MyBatis。配置与基础设施中可见 Apollo、Redis、RocketMQ、Netty 和 Elasticsearch 相关组件。具体版本应以各独立服务的依赖清单为准。</p><h2 id="各层职责" tabindex="-1">各层职责 <a class="header-anchor" href="#各层职责" aria-label="Permalink to &quot;各层职责&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>解决的问题</th></tr></thead><tbody><tr><td>HTTP 接入</td><td>接收用户与后台请求，进行鉴权和参数检查</td></tr><tr><td>Dubbo 服务</td><td>提供跨业务域的远程能力</td></tr><tr><td>业务与计算</td><td>订单规则、账户变动、撮合和结算</td></tr><tr><td>MySQL / MyBatis</td><td>业务记录与持久化数据访问</td></tr><tr><td>Redis</td><td>缓存、共享状态与业务辅助机制</td></tr><tr><td>MQ / Netty</td><td>异步事件传递与实时数据通信</td></tr></tbody></table><h2 id="选型与边界" tabindex="-1">选型与边界 <a class="header-anchor" href="#选型与边界" aria-label="Permalink to &quot;选型与边界&quot;">​</a></h2><p>远程调用、消息发送和数据库事务拥有不同的失败方式。不能因为服务都由 Spring 管理，就认为一次请求内的所有动作会一起回滚。架构设计必须明确事实记录、响应超时和后续恢复之间的关系。</p>',9)])])}const b=a(r,[["render",i]]);export{p as __pageData,b as default};
